module radix2_div (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output reg [15:0] result
);

reg [7:0] dividend_abs;
reg [7:0] divisor_abs;
reg [7:0] remainder;
reg [7:0] quotient;
reg [3:0] cnt;
reg [3:0] start_cnt;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        res_valid <= 0;
        result <= 0;
    end else if (opn_valid && !res_valid) begin
        dividend_abs <= sign ? -dividend : dividend;
        divisor_abs <= sign ? -divisor : divisor;
        remainder <= dividend_abs;
        quotient <= 0;
        cnt <= 1;
        start_cnt <= 1;
        res_valid <= 1;
    end else if (start_cnt) begin
        if (cnt == 4'd8) begin
            start_cnt <= 0;
            cnt <= 0;
            result <= {remainder, quotient};
        end else begin
            cnt <= cnt + 1;
            if (remainder >= divisor_abs) begin
                remainder <= remainder - divisor_abs;
                quotient[7-cnt] <= 1;
            end else begin
                quotient[7-cnt] <= 0;
            end
            remainder = {remainder[6:0], 1'b0};
        end
    end else begin
        res_valid <= 0;
    end
end

endmodule
